    state ResCoversCharge {
        during {
            requested_generator_power = 0.0;
            battery_discharge_power = 0.0;
            battery_charge_power = Ppv + Pw - PL;
            spare_power = 0.0;
            cutin_LNG = 0;
            cutout_LNG = 1;
            cutin_ENG3 = 0;
            cutout_ENG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state ResCoversSpare {
        during {
            requested_generator_power = 0.0;
            battery_discharge_power = 0.0;
            battery_charge_power = 0.0;
            spare_power = Ppv + Pw - PL;
            cutin_LNG = 0;
            cutout_LNG = 1;
            cutin_ENG3 = 0;
            cutout_ENG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state BatteryDischarge {
        during {
            requested_generator_power = 0.0;
            battery_discharge_power = PL - Ppv - Pw;
            battery_charge_power = 0.0;
            spare_power = 0.0;
            cutin_LNG = 0;
            cutout_LNG = 1;
            cutin_ENG3 = 0;
            cutout_ENG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGServe {
        during {
            requested_generator_power = PL - Ppv - Pw;
            battery_discharge_power = 0.0;
            battery_charge_power = 0.0;
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 0;
            cutout_ENG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGChargeMargin {
        during {
            requested_generator_power = PL - Ppv - Pw + Pgmax / 5;
            battery_discharge_power = 0.0;
            battery_charge_power = Pgmax / 5;
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 0;
            cutout_ENG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGAndEngine3Serve {
        during {
            requested_generator_power = PL - Ppv - Pw;
            battery_discharge_power = 0.0;
            battery_charge_power = 0.0;
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 1;
            cutout_ENG3 = 0;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGAndEngine3ChargeMargin {
        during {
            requested_generator_power = PL - Ppv - Pw + Pd1max / 10;
            battery_discharge_power = 0.0;
            battery_charge_power = Pd1max / 10;
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 1;
            cutout_ENG3 = 0;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGEngine3DG1ServeOrCharge {
        during {
            requested_generator_power = PL - Ppv - Pw;
            battery_discharge_power = 0.0;
            battery_charge_power = 0.0;
            if [SoC < 0.2] {
                requested_generator_power = PL - Ppv - Pw + Pd1max / 10;
                battery_charge_power = Pd1max / 10;
            }
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 1;
            cutout_ENG3 = 0;
            cutin_DG1 = 1;
            cutout_DG1 = 0;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            illegal_overload = 0;
        }
    }

    state LNGEngine3DG1DG2ServeOrCharge {
        during {
            requested_generator_power = PL - Ppv - Pw;
            battery_discharge_power = 0.0;
            battery_charge_power = 0.0;
            if [SoC < 0.2 && PL - Ppv - Pw + Pd1max / 10 <= Pgmax + eng3_Pmax + Pd1max + Pd2max] {
                requested_generator_power = PL - Ppv - Pw + Pd1max / 10;
                battery_charge_power = Pd1max / 10;
            }
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 1;
            cutout_ENG3 = 0;
            cutin_DG1 = 1;
            cutout_DG1 = 0;
            cutin_DG2 = 1;
            cutout_DG2 = 0;
            illegal_overload = 0;
        }
    }

    state OverloadIllegal {
        during {
            requested_generator_power = Pgmax + eng3_Pmax + Pd1max + Pd2max;
            battery_discharge_power = PL - Ppv - Pw - Pgmax - eng3_Pmax - Pd1max - Pd2max;
            battery_charge_power = 0.0;
            spare_power = 0.0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_ENG3 = 1;
            cutout_ENG3 = 0;
            cutin_DG1 = 1;
            cutout_DG1 = 0;
            cutin_DG2 = 1;
            cutout_DG2 = 0;
            illegal_overload = 1;
        }
    }
}
